#!/usr/bin/env python3
"""Install a 99-record, cross-region memorial route for the previous heroes."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "Assets" / "Resources" / "Content"

def read(name):
    return json.loads((ROOT / name).read_text(encoding="utf-8"))

def write(name, data):
    (ROOT / name).write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

def upsert(entries, additions):
    positions = {entry["id"]: index for index, entry in enumerate(entries)}
    for entry in additions:
        if entry["id"] in positions:
            entries[positions[entry["id"]]] = entry
        else:
            positions[entry["id"]] = len(entries)
            entries.append(entry)

# name, local title, inspect objective, Rowan scene, historical record
records = [
("Abel North", "The Toll Returned", "Compare the bridge repair slate with the toll ledger.", "Abel returned the bridge toll before asking anyone to remember his name.", "Abel North's bridge ledger separates work from credit. Three villages carried sandbags during the flood, but a later monument attributed the repaired arch to one champion. Abel crossed out that claim and listed each crew by the number of stones they moved. When the winter levy arrived, he returned the toll to households that had already paid in labor. His final route note names a meeting with the World Will after the battle, yet the contract page is missing. The surviving account can show how the bridge was repaired; it cannot prove what Abel was offered or why he left the town the next morning."),
("Beatrice Vale", "A Map with Two Banks", "Trace Beatrice's two river routes without joining their measurements.", "Beatrice measured both banks, then left the crossing marked as uncertain.", "Beatrice Vale surveyed a river that changed course every spring. Her map records the western bank from a dry season and the eastern bank after a flood; she refused to draw a single line between them. A later copy erased the dates and called the crossing permanent. Beatrice's marginal note asks future travelers to report which stones remain above water rather than trust the clean version. She carried that unfinished map through the last campaign. The archive contains no proof that she found a stable crossing, only a method for noticing when the old one failed."),
("Cato Emmer", "The Furnace Count", "Read the furnace tally beside Cato's list of cooling shifts.", "Cato counted the hours people could leave the furnace, not only the ingots it made.", "Cato Emmer kept a furnace count that included cooling time, cracked molds and the hours when workers went home. The royal copy recorded only finished ingots, making the workshop appear twice as productive as it was. Cato added a second column for water carried to the cooling yard and a third for injuries that stopped a shift. His sword was forged from a failed mold, and its uneven spine made it easy to recognize in later portraits. The record cannot say whether that blade won his final duel; it does show how a clean production total hid the cost of keeping the army supplied."),
("Delia Wren", "The Door Left Open", "Inspect the hinge marks and the evacuation tally kept beside Delia's door.", "Delia marked every open door, including the ones her order had told her to seal.", "Delia Wren served as a gate captain during a winter evacuation. Her order was to close the lower doors once the bell sounded, but she kept a list of which families had not yet crossed the courtyard. The hinge marks show that two doors were reopened after the official tally was signed. A later report called this a breach of discipline; Delia's note says the line outside was still moving. No surviving witness gives the final number of people who passed through. Her page preserves the decision and its uncertainty without turning either into a verdict."),
("Eamon Quill", "The Missing Weather Column", "Compare Eamon's storm notes with the dated roof repairs.", "Eamon wrote down the wind direction even on the nights when the signal failed.", "Eamon Quill kept weather notes for a watchtower whose roof leaked above the bell rope. The signal book blamed three missed calls on a careless keeper, but Eamon's pages show that the rope swelled whenever rain blew from the east. He asked for a roof repair before the next storm and copied the request into his private travel diary when no clerk answered. The repair date was added later in a different hand. The pages do not establish who altered the signal book; they do make it possible to test the rope in the same wind instead of repeating an accusation."),
("Faye Mercer", "The Seed Kept Dry", "Inspect the sealed seed tin and the planting dates Faye wrote under its lid.", "Faye saved one dry seed for the next season instead of spending the last of it on a display plot.", "Faye Mercer managed a garden after two failed harvests. The public ledger describes a feast plot planted for visiting officers, while the tin beneath it holds seed reserved for the next winter. Faye wrote a date on each paper wrap and noted which packets had been damp before she found them. A later gardener planted the reserve on a lower bed and recorded a smaller but steadier yield. Nothing in the record proves the seed would have fed the town alone. It does show that Faye chose continuity over a harvest large enough to be photographed."),
("Gideon Lock", "The Key without a Name", "Compare the lock teeth with Gideon's unsigned maintenance card.", "Gideon left the mechanism drawing where the next keeper could repair it without finding him.", "Gideon Lock repaired the archive gates but refused to label the master key with his name. His card shows the order of the tumblers, the direction of the spring and a warning about a brittle pin. The official inventory lists the key as lost on the night the lower hall was cleared. Gideon's later note says he gave it to a keeper whose name he had not been permitted to record. Those entries may describe the same event, but no receipt survives. The drawing remains useful to a mechanic; the archive leaves the identity of the recipient open."),
("Hesta Crane", "The Lift that Waited", "Read the counterweight marks beside Hesta's stair repair sketch.", "Hesta stopped the lift whenever a second person could not fit beside the cargo.", "Hesta Crane designed a counterweight lift for a cliff storehouse. Her sketch includes a stopping point wide enough for two people, even though the cargo register measured only sacks. The first trial failed when a loaded platform swung toward the wall; Hesta recorded the crack in the brace and marked a slower pulley ratio. A later plan removed the platform's handrail to increase capacity. Hesta's copy restores it and leaves a note that the lift should not run when the wind turns across the cliff face. Her design reduced deliveries, but it made the return journey possible for people carrying more than a sack."),
("Idris Venn", "The Page after the Oath", "Inspect the oath page and the separate list of work completed afterward.", "Idris kept the promise and the work on different pages.", "Idris Venn was praised for an oath he took before the campaign, though his own notebook spends more space on repairing wells afterward. The formal page names his sponsor and the day he swore; the work list names a mason, a child who carried chalk and a neighbor who found clean rope. Idris refused to copy those names into the oath book because they had never agreed to become part of it. A later clerk merged both pages into one heroic account. Rowan finds no reason to erase the praise, but the two records should not be treated as if they asked the same question."),
("June Harrow", "The Quiet Room", "Check the room plan against June's note on who could leave the meeting.", "June put the exit beside the speaking chair so nobody needed permission to step out.", "June Harrow arranged a council room during the last winter of the century. The first plan placed the chair of honor on a raised platform and the only door behind it. June moved the door beside the speaking chair, lowered the table and added a blank place for someone who preferred to listen. Her note does not claim that every household attended. It records who asked to stop the meeting and when the discussion resumed. The council later called the arrangement a courtesy. June described it as a way to make refusal visible before a decision was written down."),
("Kellan Pike", "The Arrow with a Blunt Point", "Inspect the arrow case and Kellan's rule for training shots.", "Kellan blunted the practice arrows after a child reached for the wrong case.", "Kellan Pike trained archers along a ridge where a miss could cross the road below. He sorted practice arrows by a blunt copper cap and stored them in a different rack from the hunting shafts. During one drill, a child opened the wrong case. Kellan halted the exercise and moved both racks indoors before the next lesson. The supply report blamed a shortage of sharp points for the delay, while his private note names the safer storage as the reason. No injury is recorded. The archive keeps the detail because a missing injury report cannot show whether the precaution was unnecessary."),
("Liora Glass", "Three Lines at the Aperture", "Compare Liora's star readings from the open and covered observation windows.", "Liora kept the clouds in her chart instead of correcting them away.", "Liora Glass measured three bright intervals through an aperture that fogged at night. Her chart includes readings from a covered window and an open one, with the cloud cover written beside each time. A published copy removed the cloudy readings and showed a regular cycle. Liora's margin argues that the cycle only looked regular after the uncertain nights were omitted. She did not identify the source beyond the aperture. The record later helped another watcher distinguish a repeated signal from the tower's own shutter, though neither page proves who sent the light."),
("Merek Thorne", "The Sounding Weight", "Inspect the repaired line where Merek marked the water depth twice.", "Merek used the same weight at both depths and still kept the readings separate.", "Merek Thorne sounded a flooded stairwell before anyone entered it. His first mark was taken after a pump stopped; the second came when the bell rope moved in a current below the landing. He tied the same brass weight to both lines and stored them in different sleeves so the lengths would not be confused. The rescue report later combined the numbers into one depth. Merek's page notes that the water was still moving. The archive cannot reconstruct the current from a still drawing, but it can show why the two measurements should not have been averaged."),
("Nessa Bell", "The Bell without a Schedule", "Read Nessa's bell test and the blank interval she left for anyone on watch.", "Nessa tested the bell at three heights but did not name a keeper for the next turn.", "Nessa Bell tested a warning bell at three heights above the harbor. The lowest position could be heard from the east path, while the upper two carried farther across open water. She wrote the listener's location beside every result and left the next testing time blank. A schedule was added by a later officer, assigning a night watch to a family that had not agreed to it. Nessa's original sheet is creased where the schedule was attached. It records an experiment, not a permanent duty, and leaves room for the next group to choose whether another test is worth the work."),
("Orin Dusk", "The Lamp in Daylight", "Compare Orin's lamp test with the afternoon fog log.", "Orin tried the lamp while the sun was up because the ridge was often hidden before dusk.", "Orin Dusk tested a signal lamp at noon after fog closed the ridge at the same hour for four days. The received plan scheduled tests after sunset, when the horizon was usually clear. Orin moved the lamp to a lower bracket and asked a watcher to record whether the flash remained distinct against the pale sky. The log contains two successful readings and one that was blocked by a passing cart. A later copy calls all three tests failures. Orin's original distinguishes weather from obstruction, a small difference that changes how the next keeper should repeat the trial."),
("Petra Wills", "A Ration Card with Margins", "Inspect Petra's ration card where she marked the portion that remained unclaimed.", "Petra left the unused portions on the count instead of assigning them to a household.", "Petra Wills distributed grain during a week when the storehouse doors could not close. Her card records each scoop and leaves a margin for portions that were not collected. An officer later divided that remainder among the families already on the list. Petra's copy keeps the amount unassigned and notes that three travelers arrived after the count. Their names are absent, but the date and grain weight remain. The page does not reveal whether the travelers returned. It warns Rowan that a complete tally can still describe only the people someone knew to count."),
("Quen Arden", "The Bridge of Two Opinions", "Read Quen's crossing report beside the two repairs made by separate crews.", "Quen refused to choose one crew's account until both could inspect the joint.", "Quen Arden inspected a bridge after two crews blamed each other for a cracked joint. One crew had replaced the west pin; the other had reset the stone seat. Quen found both repairs present and no mark showing which came first. He asked each crew to inspect the other's work before signing the report. One agreed; the other left without signing. The bridge held through the next rain, but the report does not attribute that result to either repair. Quen's page is a record of shared evidence and an unresolved disagreement, not a judgment that both accounts were equally complete."),
("Rilla Stone", "The Stone Nobody Owned", "Inspect the quarry tag and the public list of stones taken for the memorial.", "Rilla removed her family mark from the largest stone before the wall was finished.", "Rilla Stone supervised a memorial wall built from quarry blocks brought by six villages. The largest block carried her family's mark, but Rilla asked the mason to turn that face inward. The public list records dimensions and lift crews rather than ownership. A later portrait shows Rilla standing beside the block as if she had donated it herself. Her note says the stone came from a shared cut and should be described as such. No document proves which household first split it from the ridge. The wall remains, but its maker did not want size to become a claim over everyone else's labor."),
("Soren Ashby", "The Ash Jar", "Compare the ash sample label with Soren's record of where it was collected.", "Soren marked three origins on one jar because the roof leaked between shelves.", "Soren Ashby catalogued ash collected after a fire that crossed two streets. The first jars were stored under a leaking roof, and soot from the upper shelf fell into the lower trays. Soren labeled the mixture with three possible origins rather than choose the most likely one. A later catalog shortened the label to the name of the burned workshop. Soren's sketches show that the wind crossed the street in both directions during the night. The sample can identify a broad area, not a single building. Rowan keeps the uncertainty on the archive card so that a familiar name does not turn mixed evidence into proof."),
("Tovah Morrow", "The Route That Returned", "Trace Tovah's outbound and return marks without assuming the party doubled back.", "Tovah drew the return marks in a different color because she could not verify the order.", "Tovah Morrow led a survey party through a pass that closed behind them during a storm. Her outbound marks are blue; the return marks are made in charcoal after the ink froze. The official map connects them into one continuous route, although Tovah's note says the party waited in a shelter for two nights. A rescued traveler remembered a second path, but never drew it. The page lets a future surveyor find the shelter and compare the two marks. It cannot say which return path carried every member of the party."),
("Una Field", "A Field Left Unclaimed", "Inspect the boundary stakes and Una's note about permission to plant there.", "Una moved the stakes after asking the neighboring growers, not after receiving a new grant.", "Una Field planted a trial crop on a strip between two village gardens. The tax map listed the strip as Crown land, but the nearest families used it to turn carts and carry water. Una asked them before moving any boundary stake and wrote the answer in a notebook separate from the crop record. A clerk later attached her yield to the Crown ledger. The plants grew, but the harvest was never stored in the public bins. Una's account does not settle title to the land; it shows that the garden existed through an agreement not captured by the map."),
("Vance Hollis", "The Windward Brace", "Check Vance's brace sketch against the repaired sailcloth seam.", "Vance used a short brace that the crew could remove before the gust turned.", "Vance Hollis repaired a signal mast after its long brace tore the sailcloth below. His sketch uses a shorter removable strut and gives two measurements: one for calm air and one for a crosswind. The harbor copy keeps only the calm measurement. Vance wrote that the crew should remove the brace before the gust turned, but no watch schedule names who was responsible. The torn seam was repaired twice that year. His record does not prove the short brace prevented the second tear; it preserves a way to inspect the mast without leaving a fixed obstacle in the sail path."),
("Willa Dane", "The Name on the Wrong Crate", "Read Willa's correction beside the crate whose owner never signed.", "Willa removed the wrong name and left the crate in the public store until someone claimed it.", "Willa Dane handled a delivery whose crate bore the mark of a family that had left the district. She crossed out the name but did not replace it with the nearest household's mark. The contents were tools for a public well, according to the receipt, though the seal was broken before Willa saw it. She moved the crate to the shared store and waited for a claimant. A later inventory lists it as donated. Willa's correction is dated before that word appears. The record distinguishes custody from ownership and leaves the original sender unresolved."),
("Xander Holt", "The Root Beneath the Survey Nail", "Inspect the survey nail and the root path Xander refused to cut.", "Xander moved the measuring stake instead of cutting the root that crossed its line.", "Xander Holt surveyed a garden wall where a root lifted the measuring line each spring. The stone plan called for the root to be removed, but Xander moved the stake to a second mark and recorded both distances. The wall was built slightly lower than the first drawing and survived the frost without the repair crew returning. The old tree still stands in the courtyard. Its age was never measured, and Xander left no claim that it caused the wall to hold. His note shows one way to preserve a living thing while keeping the building measurements honest."),
("Yara Flint", "The Seed That Would Not Wait", "Compare Yara's first-shoot dates with the nights when frost returned.", "Yara counted the seedling that failed alongside the one that opened.", "Yara Flint tracked a row of seedlings through a late frost. She wrote the first visible shoot beside every seed, including the ones that never opened, and marked nights when the soil crusted. A published garden note reported only the earliest plant and called the strain frost-proof. Yara's private page says the early shoot came from a sheltered pot near the wall. The field bed failed twice. Her work does not identify a stronger variety, but it gives a future gardener enough detail to repeat the comparison without mistaking one protected seed for a reliable crop."),
("Zev Calder", "The Cup with a Hairline Crack", "Inspect Zev's measuring cup and the duplicate volume written on the shelf.", "Zev stopped the test when the cup's rim split instead of estimating the missing volume.", "Zev Calder measured a cistern draw with a cup that developed a hairline crack near the rim. He stopped the test, kept the vessel and wrote down the last complete pour. The public table later fills the remaining volume with an estimate from a neighboring cup. Zev's notes warn that the two cups were made by different potters. No replacement measurement survives. The result may still be useful for planning a repeat, but the total cannot be treated as a direct reading. Zev's small break in the series became the only mark that let later readers find the bad vessel."),
("Alwen Frost", "The Warm Row", "Compare Alwen's bed temperatures at sunrise and after the greenhouse shutter opened.", "Alwen did not call the warmest bed safe until she checked it after the shutter was raised.", "Alwen Frost tended a greenhouse whose west bed stayed warm after midnight. The first keeper called it proof that the buried spring was heating the soil. Alwen measured the bed before sunrise, then repeated the reading after a shutter was raised and the wall cooled. The gap narrowed on clear mornings and widened after rain. Her notebook proposes that stone retained daylight heat, but leaves the spring as an open possibility. No instrument measured the water below the floor. The record locates a useful comparison and refuses to turn warmth into a discovered source."),
("Briar North", "The Hedge with Two Owners", "Read Briar's pruning chart beside the boundary sketch both gardeners signed.", "Briar drew the hedge down its centerline so both households could change it.", "Briar North trimmed a hedge that divided two gardens without assigning the living boundary to either household. The chart records the height on both sides and the branch that sheltered a low path. One gardener wanted a straight wall; the other needed the hedge to break wind around a seed tray. Briar marked a shared centerline and asked both households to sign before cutting the thickest limb. They did not agree on its shape, but both accepted the path. The record preserves a practical compromise and its limits; it does not claim the argument ended."),
("Cress Vail", "The Empty Basket", "Inspect Cress's basket tally and the note on produce left for passersby.", "Cress counted what was taken and what she left at the gate.", "Cress Vail ran a small produce stand during a month of poor harvest. Her basket count includes vegetables sold, vegetables bartered and food left at the gate for travelers whose names were not known. A supervisor copied only the sale column into the tax book, making the stand appear to have lost half its stock. Cress's note says some produce spoiled before anyone arrived. No receipt proves how much was shared. The count is not a complete account of generosity or waste; it is a record that both occurred in the same week."),
("Dara Lorne", "The Orchard Ladder", "Check Dara's ladder repair against the branch she left uncut.", "Dara left one low branch for children to reach without climbing the ladder.", "Dara Lorne repaired orchard ladders after a rung broke beneath a full basket. Her plan lowers the first step and widens the feet, but also leaves a branch within reach of children who could not climb. The caretaker objected that the branch would reduce the next yield. Dara marked its fruit separately rather than remove it. The following harvest was not recorded, so the effect on the orchard remains unknown. The repair did pass a second adult's weight test. Dara wrote that the ladder was for the people picking fruit, not for the count alone."),
("Elowen March", "The Calendar with a Blank Week", "Read Elowen's planting calendar and the weather notes covering the blank week.", "Elowen left a week unassigned when rain made the earlier dates unreliable.", "Elowen March kept a planting calendar through a season when the first rains arrived late. The official plan assigned a crop to every week, so failed beds looked like missed duties. Elowen left one row blank after a storm and wrote the soil condition in the margin instead of shifting every date forward. A second gardener followed her calendar and harvested less, but could trace which beds had been planted into wet ground. The page cannot predict the next season. It shows why a blank interval can carry more information than a forced date."),
("Fenwick Reed", "The Reed Basket", "Inspect Fenwick's basket weave beside the reed bundles sorted by length.", "Fenwick used the short reeds too, but left them in a separate stack.", "Fenwick Reed taught a basket weave used to carry seed through the marsh path. His first sample used only long, straight reeds; the second includes short pieces joined with a double knot. The long weave held more weight, while the mixed weave flexed without splitting at the handle. A later market copy calls the second basket inferior because it carries less. Fenwick's workshop note says the mixed basket was intended for wet ground, where a rigid handle could cut the carrier's palm. Both designs have a use, but the label survived without the conditions."),
("Garrick Vale", "The Graft below the Crown", "Compare the grafting marks with the branch that bore fruit first.", "Garrick refused to name the rootstock until another winter passed.", "Garrick Vale tested a graft on a tree beside the old crown road. The upper branch flowered first, but a late frost took most of its fruit. Garrick marked the rootstock as unknown and asked another gardener to wait through one more winter before naming the cross. A market seller later called the fruit Crown Sweet and attributed the graft to Garrick alone. His own label lists the donor as a traveler who never signed it. The tree survived, while its exact lineage remains open. A useful name can guide a basket without claiming to settle ancestry."),
("Hester Moss", "The Moss on the Stone Jar", "Read Hester's humidity card beside the two jars stored on separate shelves.", "Hester kept the leaking jar in the record because it explained why one seed lot spoiled.", "Hester Moss stored seed in two stone jars above the cellar stairs. One jar sat under a dry shelf; the other collected condensation from a pipe that leaked only at dawn. A clerk emptied the damaged jar before Hester could record the lost quantity. Her humidity card preserves the dates the inside wall felt wet and the seeds began to darken. The surviving lot germinated poorly, but the other jar also lost several seeds to insects. Hester would not call either container reliable. The note remains practical because it includes the failure rather than hiding it."),
("Isolde Greer", "The Bench Facing East", "Inspect the bench placement and Isolde's observation times before comparing plant growth.", "Isolde moved the bench before moving the seed trays.", "Isolde Greer compared two seed trays and noticed that the eastern bench received a longer band of morning light. Rather than move the plants one by one, she moved the empty bench, marked its shadow and repeated the test on a cloudy day. The difference shrank, but did not disappear. A later summary said the eastern seed was stronger, leaving out its position. Isolde wrote that the trial would need identical light before anyone blamed the seed lot. Her evidence is small and incomplete, yet it prevents a favored explanation from outrunning the arrangement."),
("Jory Wren", "The Root Map", "Read Jory's root map beside the irrigation trench that stops short of the dry bed.", "Jory drew the roots he could see and left the underground section unfilled.", "Jory Wren mapped the roots along a trench where one bed stayed green and another dried before noon. He drew only the roots visible from the cut face and used dotted lines for places he had not opened. An older map extended those dots into a single underground channel. Jory's page notes that the upper bed was watered twice as often, a difference the earlier drawing omitted. No excavation tested where the roots joined. His map makes a useful planting guide without presenting unseen soil as measured ground."),
("Kestrel Dawn", "The Bell above the Water", "Compare Kestrel's bell test at dawn with the waves recorded on the same days.", "Kestrel rang the test twice because the first clear note followed a passing boat.", "Kestrel Dawn measured how a bell carried across a lake before sunrise. The first ring was swallowed by the wake of a passing boat, and the second reached a listener on the far bank. Kestrel recorded both rather than average them. The keeper's report later listed only the successful sound and set the bell as a reliable warning. Kestrel's note says it may fail during boat traffic and asks for a second method near the docks. The record does not decide which signal is best. It preserves the conditions under which one test worked."),
("Larkin Snow", "The Snow Line on the Door", "Inspect Larkin's height marks beside the days the warming room opened.", "Larkin marked the drift after the door was cleared, not before.", "Larkin Snow tracked winter drifts outside a warming room. The first measurement was taken before workers cleared the door; the next came after they moved snow into the alley. A later chart plotted both numbers as natural accumulation and blamed the wind for a sudden drop. Larkin's handwriting adds a small shovel beside the second date. The drift did become lower, but the building crew changed its shape. No instrument measured the wind that night. A future reader can still use the marks if the cleared path is counted as part of the site."),
("Maris Grey", "The Voice without a Singer", "Read Maris's sound notation beside the empty chair left in the rehearsal room.", "Maris copied the rhythm and left the speaker field blank.", "Maris Grey transcribed a rhythm heard beneath the southern stones. The pattern returned after a pause, but no person stood by the vent when the second listener arrived. Maris wrote the beats and left the speaker field blank. A rehearsal copy added a name from the choir roster, even though that singer was away from the village. Maris's page distinguishes what the listener heard from who the listener imagined. The resonance may have come from water, a bell or an unseen chamber. The record makes none of those sources certain."),
("Niall Fen", "The Reed that Bent Twice", "Inspect the reed sensor and the two flood marks Niall recorded on its stem.", "Niall left the bent reed in place long enough for another person to repeat the reading.", "Niall Fen used a reed as a temporary water marker while the stone gauge was repaired. The stem bent once when the channel rose and again when a floating branch struck it. A rushed report described one high-water event. Niall's note separates the two marks and sketches the branch caught upstream. He did not know whether the first bend came from the current or a sleeper rope. The reed was replaced the following morning, so no second observer saw it in the channel. Its two scars remain evidence of sequence, not a complete flood record."),
("Odelia Finch", "The Page Heard in Private", "Check the consent slip beside Odelia's transcript and the copy stored for public reading.", "Odelia separated the words people offered from the words they asked her to keep private.", "Odelia Finch collected a spoken account from a neighbor who agreed to share the timing of a bell but not the names spoken after it. Her transcript uses a divider between the two parts. The public copy preserved the time and omitted the private names; a later binder lost the divider and treated the entire page as one account. Odelia's consent slip is signed only for the measured interval. No surviving page expands that permission. The archive keeps the public version with its boundary visible and leaves the sealed portion untouched."),
("Perrin Shaw", "The Listening Rope", "Inspect Perrin's rope knots and the depth marks from each listening position.", "Perrin moved the listener before changing the tuning fork.", "Perrin Shaw tested a listening rope lowered through an old well. The first knot marked the depth at which a bell became clear; the second marked where water noise obscured it. When the result differed at another well, Perrin moved the listener to match the first position before replacing the fork. The new comparison narrowed the gap. A summary called the fork unreliable, but Perrin's worksheet shows that the two measurements were made at different depths. The record does not explain the sound below the stone floor. It gives a repeatable position from which to ask again."),
("Quilla Moon", "The Crescent Cut", "Compare Quilla's crescent carving with the dates when the southern window was covered.", "Quilla copied the moon-shaped mark before anyone decided what it meant.", "Quilla Moon copied a crescent cut into a stone plate beside the southern window. The cut faced east at noon, though the plate may have been moved before the archive was sealed. Quilla checked the window dates and found that a wooden shutter covered it for half the month. Her drawing preserves the shape and orientation but does not call it a calendar, a warning or a sign from beyond the lake. A later guide gave it a name. Quilla's margin asks the next surveyor to inspect the hinge before comparing the mark with the moon."),
("Rook Weaver", "The Net Repaired with Two Hands", "Inspect the net join where Rook recorded the different knot used by each crew.", "Rook kept both knot patterns on the same net instead of replacing one for the other.", "Rook Weaver repaired a fishing net after two crews brought different knot patterns to the same dock. One knot held small fish but tightened when wet; the other stretched and left gaps. Rook joined both sections and marked where the mesh changed. A buyer called the net defective because the openings were not uniform. Rook's record says it was used for separate catches in a mixed current, then repaired again after a storm. The catch log ended before the second repair was weighed. A net can be inconsistent and still make its differences visible."),
("Sable Kells", "The Note beneath the Resonator", "Read Sable's vibration marks beside the stone that held the resonator in place.", "Sable marked the stone before removing the metal plate.", "Sable Kells heard a low pulse through a metal resonator fixed to the north pier. She marked the stone's vibration before removing the plate, then listened again with the pier empty. The pulse remained, but its interval changed when a barge passed beyond the wall. A later report credited the resonator for discovering the rhythm. Sable's notes say the device made the pulse easier to count, not that it created or identified it. The source remains unknown; the observation can be repeated without turning the instrument into an answer."),
("Tamsin Drake", "The Lamp Kept Dark", "Inspect the lamp shutter and Tamsin's log for the nights when the signal was withheld.", "Tamsin recorded every night the lamp stayed dark as carefully as each flash.", "Tamsin Drake supervised a night lamp on a ridge above the choir path. She withheld the signal when mist made its direction uncertain, then wrote why the lamp had remained dark. The public tally counted only flashes and described the blank nights as missed duty. Tamsin's copy lists weather, repair and one request from a traveler who did not want the path marked. The record does not prove that every silence was deliberate; one page is missing. It does show that absence was not always failure."),
("Ulric Bell", "The Water under the Bell", "Compare Ulric's bell timing with the water level written on the same sheet.", "Ulric repeated the timing after the lake rose rather than using the morning's number.", "Ulric Bell timed a warning bell against a sound that traveled from the lake wall. The first interval was measured at low water; the second, after rain, was shorter. A copied report averaged both numbers and listed one travel time. Ulric's original places the water mark beside each test and warns that the stone channel changed when the lake rose. He did not measure the channel directly. His observation can guide a repeat at two water levels, but the result does not identify the chamber that carried the sound."),
("Veda Quill", "The Transcript with a Gap", "Inspect the missing leaf and the transcript marks Veda used where the page was torn.", "Veda left the gap marked instead of rebuilding a sentence from memory.", "Veda Quill transcribed a testimony page that tore through the middle of a sentence. She wrote the words she could still read on either side and marked the missing section with a line of dots. A later copy joined the fragments into a fluent account. Veda's margin says she remembered the speaker pausing, but not the exact words. The witness had asked to review the page and never returned. The surviving text cannot settle what was said in the gap. It can preserve the fact that the gap existed and that someone chose not to fill it."),
("Weston Rye", "The Milepost with Two Faces", "Inspect both sides of Weston's milepost before reading the travel estimate.", "Weston measured the road in both directions because the return grade was steeper.", "Weston Rye set a milepost where a road descended toward the flats and climbed sharply on the return. His first carving measured distance from the gate; the second marked the distance back from a sheltered well. A traveler copied one face into a route book and described the road as level. Weston's diagram records the slope and the point where carts stopped to cool their axles. No survey established the same distance for loaded and empty wagons. His marker answers where the road changes, not how long every journey will take."),
("Yvonne Marsh", "The Salt Jar with a Loose Seal", "Check Yvonne's seal sketch against the crystals in the jar's threaded rim.", "Yvonne wrote the leak down before opening the jar to save the remaining sample.", "Yvonne Marsh stored a salt sample in a jar whose seal loosened during a dry week. She recorded the crystals on the thread before opening it and moving the remaining sample to waxed paper. The official stock count treated the jar as full because no one had weighed it after the leak. Yvonne's note gives the last reliable weight and the time she found the seal open. She does not say who used the jar. The sample still identifies its basin, but not the full amount that entered the store."),
("Bram Keller", "The Road Guard's Empty Bowl", "Read Bram's ration bowl count alongside the night watch rota.", "Bram kept a bowl for the guard who asked not to be listed by household.", "Bram Keller ran a road guard post where travelers arrived after the ration list was closed. He set aside a bowl for anyone on an unplanned night watch and did not attach it to a household name. The rota counts three watches, while the kitchen sheet records four bowls used on two nights. A later clerk assumed the extra portions were stolen. Bram's note says a guard asked to remain unnamed. The records do not prove that the same person ate both meals. They show that a rota and a kitchen count measured different things."),
("Corra Voss", "The Arrow Turned Away", "Inspect the impact mark and the road bend Corra told the team not to widen.", "Corra moved the target from the road bend instead of clearing the blind turn.", "Corra Voss tested an arrow signal from a bend where two caravans could not see each other. The first proposal widened the road and removed a stand of trees. Corra shifted the target board above the stones and asked the teams to slow before the turn instead. One caravan saw the signal; another arrived in rain and missed it. Her report records both outcomes and the weather. The road was not widened that season, though the archive never says whether the tree line was protected for any other reason."),
("Dain Harrow", "The Chain Not Cut", "Read Dain's chain tally beside the link that bears a second hammer mark.", "Dain counted the repaired link as evidence of use, not evidence of who repaired it.", "Dain Harrow inspected a chain used to draw a crossing gate. One link carried two hammer marks, and the pin had been replaced with a different alloy. The guard's report called the chain sabotaged; Dain's measurements could not distinguish a repair from an attempt to weaken it. He marked the link and ordered a spare kept near the gate. The chain later failed at another joint. The record cannot identify who altered the first link, but it prevents that uncertain mark from being used as the sole explanation for the failure."),
("Elsie Flint", "The Tag Returned Blank", "Inspect the blank return tag and the separate tally of cargo placed beside it.", "Elsie returned the tag without a name because the carrier had not given one.", "Elsie Flint worked a toll desk where travelers could refuse to leave a name. She returned one cargo tag blank and attached a separate tally showing the parcel's weight and destination. The next clerk copied the weight into a household account because the destination was a village name. Elsie's note says she never saw who carried it beyond the gate. The parcel may have been delivered, but no receipt confirms that. Her paperwork keeps a useful route record while refusing to turn a destination into the identity of a person."),
("Fenn Orle", "The Three Kinds of Dust", "Compare Fenn's dust samples from the outer wall, the axle and the sheltered scale.", "Fenn stored each dust sample apart even when the sacks used the same road.", "Fenn Orle collected dust after a caravan returned with damaged sacks. The outer wall held pale grit, the axle carried darker sand and the sheltered scale had a thin line of salt. He stored the samples apart because the wagon had crossed both quarry road and tidal flats. A trader mixed them into one bag to show the damage to a buyer. Fenn's note records where each sample came from, but no chemical test was available. The dust can narrow a route; it cannot prove which wheel crossed the salt flats first."),
("Greer Vale", "The Toll Waived in Rain", "Read Greer's weather note beside the crossing fees removed from the ledger.", "Greer marked the fee waived because the plank bridge was closed, not because the caravan was favored.", "Greer Vale waived a crossing fee during a week of heavy rain. The plank bridge had been closed after one support rope frayed, and every wagon used the longer ridge road. A complaint described the waiver as a gift to a favored caravan. Greer's ledger lists the closure notice and the repair request beside the removed fees. One family carried its goods by hand and still paid the foot toll. The record does not establish whether the policy was fair to everyone, but it explains the condition under which one charge was removed."),
("Harlan Beck", "The Cart with a Cracked Wheel", "Inspect the cracked wheel and the road section Harlan marked as unsafe for a full load.", "Harlan unloaded the cart before taking the measurement a second time.", "Harlan Beck tested a cart wheel after a crack appeared near the rim. His first measurement was taken while the cart carried a full salt load; the second followed unloading and cooling. The rim narrowed between readings, so he marked the road grade and temperature beside each one. The repair shop copied only the smaller measurement into its part order. Harlan's field page warns that the wheel should not be judged by one unloaded test. The wagon never returned for a final reading, leaving the repair unconfirmed."),
("Iona Slate", "The Mark in the Tollhouse Floor", "Compare Iona's chalk mark with the worn groove below the tollhouse hatch.", "Iona marked the groove before the floor was swept clean.", "Iona Slate noticed a groove running from the tollhouse hatch toward a storage wall. The first clerk said it was made by a handcart; Iona traced its width and found that it narrowed near the wall. She placed a chalk mark at each end before the floor was swept. A later work crew covered the groove with a plank, and no object was recovered. The shape may match a dragged crate, but the floor record cannot establish what was inside it or who moved it."),
("Jessa Ward", "The Escort Who Waited", "Read Jessa's escort log beside the empty chair reserved at the wayhouse.", "Jessa waited until the traveler was ready to leave the room, not until the rota said so.", "Jessa Ward escorted travelers between two toll posts. One person asked to remain at the wayhouse until morning, though the rota showed the departure party as complete. Jessa crossed out her own departure time and wrote the wait beside a blank chair in the room plan. The official log later counted her late arrival as a missed shift. No account records why the traveler needed the extra night. Jessa's note states only that an escort was not a deadline."),
("Kade Lorne", "The Bell on the Back Road", "Inspect the back-road bell and Kade's record of who could hear it from the ditch.", "Kade tested from the low ditch because the road itself hid the sound.", "Kade Lorne fitted a bell on the back road after two carts met on a blind descent. He tested it from the road, then from the drainage ditch where a foot traveler would wait for the carts to pass. The sound reached the road clearly but arrived late below the bank. A later survey measured only the road. Kade's note requests a second bell lower on the slope, though none appears in the next inventory. The original test identifies a blind spot without proving that another bell would have solved it."),
("Lyle Mercer", "The Cup Kept for Winter", "Inspect Lyle's cracked cup beside the cistern inventory and the winter replacement order.", "Lyle kept the broken cup after the replacement order arrived.", "Lyle Mercer compared two cistern cups through a winter when the standard vessel developed a crack. The new cup held more water, but its handle forced a smaller grip for a person with stiff fingers. Lyle measured both volumes and attached a note about the handle. The storehouse ordered the new cup after reading only the capacity column. Lyle kept the cracked one so a later worker could repeat the comparison. Neither measure tells whether the cistern itself lost water between the two tests."),
("Mina Crow", "The Grain below the Scale", "Compare Mina's floor sweepings with the weight that remained in the hopper.", "Mina swept the spill into a separate jar instead of adding it back to the ration total.", "Mina Crow weighed grain at a hopper whose floor had a gap beneath the scale. She swept the fallen kernels into a separate jar and wrote the weight beside the amount issued. A store report later included the jar as usable stock, though several kernels had been ground into dust by carts. Mina's note says the remainder should be inspected before it is poured back. The record does not show how much was recovered or fed to birds. It does keep a spill from becoming an invisible correction to the ration total."),
("Nolan Wren", "The Channel with a Closed Gate", "Read Nolan's flow marks before and after the upper gate was opened.", "Nolan wrote down the time the gate moved before comparing the two water lines.", "Nolan Wren measured a channel while the upper gate was closed. The first line fell over six minutes; after the gate opened, the next line rose, but water also entered from a side ditch. Nolan wrote down both events and asked that the ditch be measured separately. A public notice described the gate as restoring the full flow. The marks cannot establish that conclusion because two sources changed at once. Nolan's page preserves timing, not a single cause."),
("Orla Pike", "The Silt in the Second Jar", "Inspect Orla's jars and the note showing which one settled before the test.", "Orla did not pour the clearer jar first after she saw the silt still moving.", "Orla Pike took two jars of water from opposite sides of a settling basin. One looked clear at first glance, but a second reading showed fine silt still moving along the glass. She waited before pouring either jar into a filter test. The public sheet records only the clearer sample. Orla's copy adds the waiting time and the sediment line near the base. The test does not certify water quality, but it demonstrates why appearance can change between the first and second observation."),
("Piers Reed", "The Valve Turned Halfway", "Inspect the valve stop and Piers's sketch of the position between open and closed.", "Piers marked the halfway notch because the handle could slip past the full-open stop.", "Piers Reed repaired a valve whose handle slipped beyond its full-open stop. He cut a shallow notch halfway between open and closed so the next operator could hold a measured flow. The maintenance sheet called the mark an obstruction and ordered it filed away. Piers's sketch shows a worn bolt that let the handle jump under pressure. No test was made after the bolt was replaced. The record keeps the half-flow position as a clue to the failure, not as a recommended setting."),
("Rhea Fable", "The Note That Was Not a Forecast", "Read Rhea's market note beside the forecast copied to the public board.", "Rhea wrote what the clouds had done, not what she promised they would do tomorrow.", "Rhea Fable recorded cloud cover above the basin for a planting group that needed to decide whether to cover its trays. Her page describes wind, color and time without predicting rain. A public board copied the notes beneath a heading called Tomorrow's Weather. Several gardeners relied on the heading and left their trays uncovered. Rhea's correction says she had not forecast the next day. The plants were not counted afterward. Her record matters because observations and predictions ask different questions even when they share the same sky."),
("Stellan Frost", "The Pipe under the Stairs", "Inspect the pipe joint beside Stellan's frost line and repair date.", "Stellan drew the frost line before the warm pipe was insulated.", "Stellan Frost found ice on the cellar stairs above a pipe that carried water from the west wall. He marked where frost began, then returned after insulation was installed. The line moved lower but did not disappear. A maintenance report declared the pipe fixed because the nearest step stayed dry. Stellan's drawing notes that the cold followed the wall seam below the visible steps. The cellar was closed before anyone opened the plaster. His two readings show change after repair, not proof that the leak or cold source was found."),
("Talia Wray", "The Basin's Second Outlet", "Compare Talia's outlet sketch with the stone trench that ends beneath the seed store.", "Talia left the trench's unseen section dashed so the next crew would not dig on a guess.", "Talia Wray mapped a second outlet from the basin after water appeared near the seed store wall. She traced the visible trench to a flat stone and used a dashed line beyond it. A later map extended the line to the river, drawing a direct route that no one had excavated. Talia's notes include one dry day when no water appeared and one rainy day when it did. That pattern could reflect runoff, a blocked pipe or a hidden channel. Her page marks the place for another survey without selecting among them."),
("Ulna Voss", "The Receipt with No Quantity", "Inspect Ulna's water receipt and the unmarked line where a volume should have been written.", "Ulna returned the receipt unsigned because the bucket had not been measured.", "Ulna Voss recorded water carried to an upper bed during a dry week. The receipt lists the carrier and destination but leaves the volume blank because the bucket had no fill mark. A supervisor filled in a standard amount based on the household's usual bucket. Ulna crossed out the estimate and returned the receipt unsigned. The crop survived, but no one measured how much water it received. The archive cannot recover the missing volume; it can preserve why the quantity should not be treated as known."),
("Vesper Hart", "The Cooling Pan", "Read Vesper's metal temperature notes beside the time each pan left the fire.", "Vesper marked the pan's time away from the fire before comparing the grain.", "Vesper Hart tested a cooling pan used to dry grain near the lower kiln. The first sample came from a pan removed from the fire only moments earlier; the second waited until the rim stopped glowing. The grain cracked less in the second trial, but the portions were not weighed equally. Vesper asked for another test with matched measures. A later recipe kept the cooling interval and dropped the weight note. Her record preserves a useful question without claiming that the pan alone caused the difference."),
("Wynn Calder", "The Weight behind the Door", "Inspect Wynn's counterweight and the mark where a sack struck the door frame.", "Wynn kept the door mark in the drawing so the next operator would know when to stop.", "Wynn Calder balanced a storehouse door with a counterweight made from old cistern iron. It lifted smoothly until a sack was placed against the frame. Wynn measured the collision mark and shortened the pull rope. The repair stopped the door from swinging as far, but the store could no longer move the widest barrel through it. A later plan lists the door as fully repaired. Wynn's note says the tradeoff remained. The measure offers a safer stopping point, not a way to keep both the old opening and the new limit."),
("Xena Muir", "The Lime Line", "Compare Xena's chalk line with the marks left after the wall dried.", "Xena dated the line before painting over the wet stone.", "Xena Muir marked a damp wall with lime before the masons painted it. After two days, the upper line faded first; the lower mark remained visible. A repair ticket attributed the difference to poor paint, but Xena's note says the upper stones had received more sun. She did not open the wall to look for a pipe. The paint was replaced before the next rain, so the test was not repeated under the same conditions. Her page helps locate the damp area without claiming to know what carried water through it."),
("Yestin Crowe", "The Roster in Pencil", "Inspect Yestin's pencil roster beside the ink copy signed after the drill.", "Yestin used pencil because the cadets were still deciding who wanted a night turn.", "Yestin Crowe kept a cadet roster in pencil while a new night drill was being proposed. The ink copy signed afterward includes three names whose initials appear only on the second page. Yestin's pencil list has blank spaces beside those shifts and a note that the cadets had not chosen a schedule. The drill took place, but no report records who filled every turn. His page does not prove the later signatures were false; it shows that the decision was still open when he made the first list."),
("Zola Marsh", "The Cloak on the Empty Cot", "Read Zola's cot inventory beside the cloak tag whose owner was never identified.", "Zola recorded the cloak and left the name field empty.", "Zola Marsh counted equipment in an emptied barracks. One cot held a cloak with a torn sleeve and a tag showing a repair date but no name. The inventory clerk added the nearest cadet's initials, then removed them after Zola asked who had authorized the change. The cloak was sent to the common laundry. No later receipt identifies who reclaimed it. Zola's list records a real object and a real absence without turning the nearest bed into proof of ownership."),
("Ansel Ward", "The Chalk under the Bench", "Inspect the chalk marks under Ansel's bench and compare them with the lesson order.", "Ansel placed a mark low enough for a cadet to reach without climbing the bench.", "Ansel Ward taught map reading in a hall where the top board could only be reached by stepping onto a bench. He drew a second route at seated height and used chalk beneath the bench to mark the place where the map turned. The instructor's copy shows only the raised board. Ansel wrote that a cadet with a sprained ankle had followed the low marks successfully, but did not include the student's name. The lesson was later adopted without the second route. His chalk line is evidence that the method existed before the official copy."),
("Blythe Dorne", "The Letter Sent Back Twice", "Read Blythe's two return stamps before comparing the last address written on the envelope.", "Blythe preserved both stamps because the second return did not explain the first.", "Blythe Dorne received an envelope sent between two barracks offices. It came back once with no reason marked, then again with a new routing stamp. The final address is legible, but the page does not show whether the recipient ever saw the letter. Blythe copied both stamps before the envelope was filed as undeliverable. A later clerk recorded only the last return and dated the failure to the sender. The two stamps establish a route through the offices, not the choices of the person who waited for the letter."),
("Caris Holt", "The Buckler with a Bent Rim", "Inspect Caris's buckler repair and the sparring note written before its final use.", "Caris replaced the rim after a practice blow, not after a battle.", "Caris Holt repaired a cadet buckler whose rim bent during supervised sparring. The armour ledger lists the item as battle-damaged, though Caris's training note records a practice strike from a wooden blade. She replaced one rivet and kept the shield in the practice rack. A later portrait shows the same buckler beside a campaign banner. It may have been carried afterward, but the repair record cannot establish where. Caris's page gives the next armourer a rivet size and keeps the event that caused the first bend attached to the item."),
("Doran Pryce", "The Gate Drill at Noon", "Compare Doran's midday drill marks with the shadows crossing the southern gate.", "Doran scheduled the drill when the shadow covered the latch, then wrote down why.", "Doran Pryce tested a gate drill at noon because the southern latch disappeared in glare during the afternoon change. The first group opened it correctly; the second waited for a lantern although the sun was still above the wall. Doran moved the practice mark to the shaded side and asked cadets to repeat the sequence without a spoken cue. The roster says the drill was completed, but does not list the observers. His note records a visual condition, not whether every recruit understood the gate."),
("Eira North", "The Empty Place at Roll Call", "Inspect Eira's roster where she separated absence from an unreported transfer.", "Eira left the cot number open until the transfer docket arrived.", "Eira North counted cots at morning roll call and found one place empty. The first roster marked the occupant absent; Eira left that box blank because a transfer docket had been issued without a return date. A copy filed later marks the cadet as missing. The docket's destination is clear, but no receipt proves arrival. Eira's page keeps the cot count separate from the person's status. It cannot say where the cadet went; it does prevent a vacant bed from becoming a conclusion."),
("Ferris Quill", "The Mended Page", "Read Ferris's stitching pattern and the two text fragments it keeps apart.", "Ferris stitched the page without forcing the torn sentences together.", "Ferris Quill repaired a register torn through a list of cadet transfers. He used pale thread across the break and dark thread around the missing corner so a later reader could see where the paper ended. Two lines meet near the tear but do not align. A clerk copied them as one sentence. Ferris's stitching leaves both fragments visible and provides a way to flatten the page without hiding the gap. The original wording may never be recovered. His repair preserves the shape of the evidence rather than restoring a version that only reads more smoothly."),
("Harlan Moss", "The Drill Whistle", "Inspect Harlan's whistle test beside the wall that blocked the second signal.", "Harlan changed the place of the caller before changing the pitch.", "Harlan Moss tested a drill whistle from the north courtyard. One tone carried past the wall; another sounded louder near the caller but disappeared at the barracks door. He moved the caller to the open arch and repeated both signals before changing the whistle. The second location altered the result more than the pitch. The official note recommends the higher tone and leaves out the relocation. Harlan's card keeps the caller's position on the same line as the sound reading. The drill can be repeated only if that position is restored."),
("Ina Bell", "The Needle on the Map", "Read Ina's compass bearing beside the iron gate that pulled the needle east.", "Ina wrote the gate's position because the compass changed when she stepped inside.", "Ina Bell used a compass to mark a practice route through the old eastern gate. Outside, the needle held steady; inside, it pulled toward the gate hinge. She recorded both readings and traced the iron plates around the threshold. A later map copies the second bearing as the true north line. Ina's note says the compass should be checked outside before the route is drawn. The gate was never dismantled, so the source of the pull is not fully known."),
("Joryn Ash", "The Blank Name Badge", "Inspect the badge backing and the form where Joryn refused to guess its owner.", "Joryn kept the cadet number and left the name unset.", "Joryn Ash found a name badge beneath an unused bunk. The brass backing carried a cadet number but the paper face had been scraped clean. Joryn copied the number and left the name field blank rather than match it to a transfer list with similar initials. The badge was returned to the quartermaster, whose receipt says only that one tag came back. It could belong to any cadet listed in that year. Joryn's form keeps a small object from becoming a confident but unsupported identity."),
("Kira Fen", "The Training Blade Stored Low", "Check Kira's rack plan and the practice blade she moved below shoulder height.", "Kira lowered one rack so a cadet recovering from a wrist injury could return it.", "Kira Fen rearranged a training rack after a cadet struggled to return a blade with one injured wrist. The usual racks were mounted at shoulder height to save floor space. Kira lowered one section and marked it for practice weapons only. The quartermaster objected that the lower rack could be mistaken for a public store. Kira added a painted border and tested whether the distinction could be seen from the door. The next audit lists one blade in the low rack but no user. The repair changed access without naming the person it helped."),
("Lorne Vey", "The Cadence without Orders", "Compare Lorne's drum pattern with the drill schedule that was added later.", "Lorne wrote the rhythm but did not make it a command.", "Lorne Vey tested a drum cadence meant to help cadets keep pace across the inner yard. The first note sheet labels the pattern a practice cue, while a later schedule uses the same beats to order a night formation. Lorne's copy includes a line that the drummer may stop if the group loses the rhythm. The schedule omits it. No report says whether the pattern was ever used in a field march. The page preserves the difference between a tool for coordination and an order that leaves no room to stop."),
("Maelin Quill", "The First Name on the Muster Slate", "Inspect Maelin's slate beside the revised list where the number of survivors changed.", "Maelin erased the total but left the earlier count legible underneath.", "Maelin Quill kept a muster slate after the Ashfall attack. The first total counted people who had reached the east stair; the second counted those still present at dawn. Maelin erased neither number completely, leaving the earlier chalk visible beneath a pale wash. A later summary chose the larger total and called everyone accounted for. Maelin's margin says the stair had not been checked after the last bell. The slate cannot give a final number of survivors, but it shows why two counts were taken at different times."),
("Oren Black", "The Door Bar Measured Twice", "Compare Oren's two door-bar measurements with the direction each force came from.", "Oren measured the bar from both sides because the first scrape had no arrow.", "Oren Black inspected a door bar after the village shelter was found open. He measured the scrape on the inner face, then the outer face, because the first report did not say which direction the force came from. The two marks differed in height by less than a finger. Oren could not tell whether the bar had been lifted, knocked aside or removed before the shelter filled. A witness later recalled a sound but not its source. The report holds both measurements and leaves responsibility unassigned."),
("Piper Wren", "The Blanket with Two Repairs", "Inspect the blanket tags and the separate dates Piper stitched into its hem.", "Piper wrote the repair dates in thread so the warmth would not depend on the inventory.", "Piper Wren repaired a shelter blanket twice during a cold week. The first patch covered a tear at the lower edge; the second added a strip where the seam pulled away from a cot frame. The inventory describes one blanket in usable condition. Piper's sewn dates show it was returned to the shelter between both repairs, though the handoff list has a missing evening. No name appears on the hem. The cloth served more than one person, and the ledger cannot say who slept beneath it on every night."),
("Quinley Vale", "The Bell Heard from the Well", "Read Quinley's hearing notes from above the well and from inside its shelter.", "Quinley logged the listener's shelter before judging whether the bell carried.", "Quinley Vale tested whether the village bell could be heard from a well shelter. The signal reached the entrance but not the lower stone room while rain struck the roof. After the rain passed, one listener heard it from the stairs. The note records the shelter door position and the listener's location. A later report calls the test a clear success. Quinley's original says the result changed with the roof noise. The bell may still serve the shelter, but the record does not describe a quiet room when the weather turns."),
("Riven Moss", "The Boots Left by the Hearth", "Inspect the boot tally beside Riven's note about what could not be identified.", "Riven counted the boots, not the people who might have worn them.", "Riven Moss found three pairs of boots by the hearth after a group left through the west path. One pair was too small for an adult; another had a repaired heel matching no mark in the shelter ledger. Riven counted the footwear and left the number of travelers blank. A later story said three villagers had escaped. The boots could have belonged to people who shared pairs or to visitors not on the roll. Riven's note records objects that survived the fire without using them to invent names."),
("Sybil Crane", "The Well Rope Shortened", "Compare Sybil's rope length with the water depth recorded before the bucket was lowered.", "Sybil marked the knot she added after the first bucket struck stone.", "Sybil Crane replaced a well rope shortened by a frayed section. She measured the water depth before tying a new knot, then recorded the bucket's stop point after the repair. The public card lists only the new rope length. Sybil's note warns that the bucket may touch the bottom when the water is low. No second depth reading was taken that week. The record helps a later keeper choose a safe test but cannot tell whether the well fell or the rope measurement changed."),
("Tavian Reed", "The Ash on the Window Ledge", "Inspect Tavian's ash sample beside the wind direction drawn on the back of the frame.", "Tavian sampled the inner and outer ledges separately.", "Tavian Reed gathered ash from both sides of a shelter window after the fire. The inner ledge held gray dust from a collapsed roof; the outer ledge carried darker flecks blown from the south. Tavian stored them in separate paper folds and drew the wind direction on the frame backing. A public report lists one sample from the house. It does not mention that the roof fell before the second sweep. Tavian's pages do not identify the fire's starting point, but they preserve two different deposits where the summary made one."),
("Ulla Stone", "The Stone Set aside for a Name", "Read Ulla's memorial layout and the blank space kept beside each inscribed stone.", "Ulla planned room for later corrections before the names were carved.", "Ulla Stone laid out a memorial path where families could add names after confirming the spelling. The first design used a fixed number of blocks, but Ulla left a gap at each turn for a correction plate. The mason worried that blank spaces would make the wall look unfinished. Ulla argued that a stone cut in error would last longer than the mistake. Several plates were added later, though no record says who requested each one. The path can hold a correction; it cannot restore a name nobody is able to verify."),
("Virgil Dawn", "The Morning Count", "Compare Virgil's first-light count with the number written after the bell.", "Virgil recorded when each count happened instead of forcing the two totals together.", "Virgil Dawn counted people at the east gate before sunrise and again after the warning bell. The first tally included those sleeping nearby; the second included travelers who arrived after the road opened. A town summary merged both columns and described one large crowd. Virgil wrote the hour beside each number and noted that some people crossed twice to carry water. His record cannot deduplicate every crossing because no names were taken. It still shows that the two totals were not measurements of the same group."),
("Wren Hollis", "The Flight of the Paper Names", "Inspect the roof beam where Wren found the roll after the wind shifted.", "Wren pinned the loose roll to the beam before reading the names aloud.", "Wren Hollis recovered a paper roll blown from the shelter desk during a roof repair. The first sheet landed inside the courtyard; the second was caught under a western beam. Wren pinned both pages and asked two witnesses to confirm their order before reading. A clerk later filed them as one list. The ink on the underside is faint, and a few names remain uncertain. Wren's note says the roll should not be copied from the sequence of the pages alone. The wind changed the order before any person did."),
("Xavia March", "The Three Marks on the Wall", "Compare Xavia's wall marks with the three places where people waited during the evacuation.", "Xavia kept three heights on one wall because no one knew which mark meant the water had stopped.", "Xavia March recorded three water marks inside a shelter wall after the cellar flooded. The lowest line came from a damp boot; the middle one from a bucket carried through the room; the highest was still visible after the floor dried. A later report called them three flood levels. Xavia's page labels only one as water and asks the next keeper to check the chalk composition. No laboratory sample exists. The wall preserves the positions, but not a settled cause for each mark."),
("Ysra Calder", "The Seat at the End of the Table", "Read Ysra's seating plan and the separate note that allowed the last guest to leave.", "Ysra kept an open seat near the door so the meeting could end without a public refusal.", "Ysra Calder arranged a meeting for families whose homes had been destroyed. The official plan placed the speaker at the center; Ysra moved one chair close to the door and left it unnamed. A note says the last guest could leave without explaining why. The minutes record one early departure but do not say whether that person used the chair. Ysra's plan does not prove the meeting felt safe to everyone. It preserves a concrete choice about the room that later minutes left out."),
("Zander Flint", "The Blade without a Prize", "Inspect Zander's sword rack and the repair card that separated it from the victory display.", "Zander returned the blade to the repair rack before the victory feast.", "Zander Flint won a duel during the last Ashfall campaign, then returned his sword to the repair rack instead of placing it on the feast table. The blade needed a new guard and a grip wrap that no longer slipped in rain. A painter copied its shape into the victory mural before the weapon was repaired. Zander's card lists the missing rivet and names the smith who later replaced it. The sword became a symbol after the image was made, but the record begins with maintenance and the person who kept it usable."),
(
    "Zadie Mercer",
    "The Bell That Waited for Dawn",
    "Read Zadie's watch card beside the bell rope and the unclaimed first shift.",
    "Zadie left the rope untouched until the night keeper returned to the tower.",
    "Zadie Mercer kept the night bell while the eastern tower was being repaired. The roster gave her the final hour, but no one had named who would take the first morning shift. She tied a note to the rope asking the next keeper to answer before ringing. The dawn log records a bell at first light and a second response several minutes later. It does not say which keeper made either sound. Zadie preserved the gap in the record rather than assigning a hand to the rope."
),
]

locations = [
    "last_oath_reach", "outerwake_archive", "greenwake_refuge", "choir_beneath_lake",
    "salt_road", "cinderwell_basin", "dawnkeep_outpost", "ashfall_village",
]
counts = [12, 12, 13, 12, 12, 12, 13, 13]
assert len(records) == 99 and sum(counts) == 99
visuals = ["document", "sealed_case", "noticeboard", "herb_ledger", "seed_cradle", "stone_rill"]
positions = [
    (-8.4, 3.7), (-4.2, 3.7), (0.0, 3.7), (4.2, 3.7), (8.4, 3.7),
    (-8.4, 1.1), (-4.2, 1.1), (0.0, 1.1), (4.2, 1.1), (8.4, 1.1),
    (-8.4, -1.5), (-4.2, -1.5), (0.0, -1.5),
]

quests, dialogues, codex, landmarks = [], [], [], []
record_index = 0
previous_quest = "last_oath_records"
for region, group_count in zip(locations, counts):
    for local_index in range(group_count):
        record_index += 1
        number = record_index
        name, short_title, objective, scene, body = records[number - 1]
        qid = f"side_hero_legacy_{number:03d}"
        dialogue_id = f"rowan_hero_legacy_{number:03d}"
        target = f"hero_legacy_{number:03d}_record"
        marker = f"hero_legacy_{number:03d}_marker"
        x, y = positions[local_index]
        title = f"{name}: {short_title}"
        dialogues.append({
            "id": dialogue_id,
            "speakerName": "ROWAN HALE",
            "lines": [
                f"The last roll gave {name} a place in the century. This page says what the monument left out.",
                scene
            ]
        })
        quests.append({
            "id": qid,
            "arcId": "two_last_oaths",
            "stage": -1,
            "type": "side",
            "locationId": region,
            "giverId": "rowan_hale",
            "title": title,
            "objective": objective,
            "prerequisiteIds": [previous_quest],
            "objectives": [{
                "id": "read_legacy_record",
                "kind": "inspect",
                "targetId": target,
                "requiredCount": 1,
                "description": objective,
                "dialogueId": dialogue_id
            }],
            "reward": {"gold": 2, "items": []}
        })
        codex.append({
            "id": f"hero_legacy_{number:03d}_record",
            "title": title,
            "category": "The Hundredth Roll",
            "writtenBy": "Rowan Hale",
            "unlockQuestId": qid,
            "body": body
        })
        landmarks.append({
            "id": marker,
            "locationId": region,
            "displayName": f"Century Archive Fragment {number:02d}",
            "targetId": target,
            "visualId": visuals[(number - 1) % len(visuals)],
            "positionX": x,
            "positionY": y,
            "scale": 0.085
        })
        previous_quest = qid

for filename, additions in [
    ("prologue_quests.json", quests),
    ("dialogue_catalog.json", dialogues),
    ("codex_catalog.json", codex),
    ("quest_landmarks.json", landmarks),
]:
    catalog = read(filename)
    upsert(catalog["entries"], additions)
    write(filename, catalog)

print(f"Installed {len(quests)} memorial quests, {len(dialogues)} scenes, {len(codex)} biographies and {len(landmarks)} regional records.")
